shader_type canvas_item;

void fragment() {
	float across = abs(UV.x - 0.5);
	float band = step(across, 0.05);
	COLOR = vec4(0.37, 0.64, 0.57, band);
}

shader_type canvas_item;

void fragment() {
	float x = abs(UV.x - 0.5);
	float y = abs(UV.y - 0.5);
	float vertical = step(x, 0.05);
	float horizontal = step(y, 0.05);
	float mask = max(vertical, horizontal);
	COLOR = vec4(0.37, 0.64, 0.57, mask);
}

shader_type canvas_item;

void fragment() {
	float x = abs(UV.x - 0.5);
	float y = abs(UV.y - 0.5);
	float not_too_far = step(y, 0.35);
	float near_line = step(x, 0.03);
	float mask = not_too_far * near_line;
	COLOR = vec4(0.37, 0.64, 0.57, mask);
}

shader_type canvas_item;

void fragment() {
	float x = abs(UV.x - 0.5);
	float y = abs(UV.y - 0.5);
	float far_enough = step(0.1, y);
	float not_too_far = step(y, 0.35);
	float near_line = step(x, 0.03);
	float mask = far_enough * not_too_far * near_line;
	COLOR = vec4(0.37, 0.64, 0.57, mask);
}

shader_type canvas_item;

void fragment() {
	float x = abs(UV.x - 0.5);
	float y = abs(UV.y - 0.5);
	float v = step(0.1, y) * step(y, 0.35) * step(x, 0.03);
	float h = step(0.1, x) * step(x, 0.35) * step(y, 0.03);
	float mask = max(v, h);
	COLOR = vec4(0.37, 0.64, 0.57, mask);
}
